-- 197-country seed for Supabase.
-- Sources: REST Countries independent countries + World Bank country income groups.
-- Manual additions for 197-country app list: Palestine (PS) and Taiwan (TW).
-- Tier rule: tier_1 = selected priority markets; tier_2 = high/upper-middle income or population >= 50M; tier_3 = remaining countries.

do $$
begin
  create type country_tier as enum ('tier_1', 'tier_2', 'tier_3');
exception
  when duplicate_object then null;
end;
$$;

create table if not exists public.countries (
  id bigint generated always as identity primary key,
  name text not null,
  official_name text,
  iso2 text not null unique,
  iso3 text not null unique,
  continent text not null,
  region text not null,
  subregion text,
  population bigint,
  un_member boolean not null default false,
  income_group text,
  income_code text,
  tier country_tier not null default 'tier_3',
  is_active boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index if not exists countries_continent_idx on public.countries (continent);
create index if not exists countries_tier_idx on public.countries (tier);
create index if not exists countries_region_idx on public.countries (region);

